window.CFC_2025_QUESTIONS = [{"id":"cfc-2025.1-tipo1-q1","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":1,"subject":"Português","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 1\n\nUm cartaz, na porta de um supermercado, dizia: “Compre hoje! Amanhã pode estar mais caro!” Esse cartaz","options":["aconselha o cliente a economizar.","dá ordem ao cliente para ganhar tempo.","chama a atenção do cliente para a possível falta de produtos.","pretende ensinar o cliente a controlar seu orçamento."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q2","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":2,"subject":"Português","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 2\n\nUm famoso escritor falou sobre a leitura: “A leitura é para a mente o que a ginástica é para o corpo.” Com essa frase, o autor quer dizer que","options":["exercícios físicos devem ser feitos todos os dias.","a leitura, como a ginástica, deve ser feita diariamente.","a leitura enriquece o nosso conhecimento.","exercícios físicos e leitura fortalecem o corpo."],"answer":null,"officialAnswer":"Anulada","annulled":true,"explanation":"Questão anulada no gabarito definitivo da FGV; não pontua.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q3","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":3,"subject":"Matemática Financeira e Estatística","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 3\n\nUma caixa contém seis bolas brancas e quatro bolas azuis, todas de mesmo tamanho. Se sortearmos ao acaso 3 dessas bolas, sem reposição, a probabilidade de que todas sejam brancas é igual a","options":["1/3.","1/4.","1/5.","1/6."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q4","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":4,"subject":"Matemática Financeira e Estatística","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 4\n\nEm 2023, uma universidade tradicional que, até então, só ofertava cursos presenciais de graduação, resolveu se arriscar em um novo projeto. Tratava -se da abertura de seu primeiro curso 100% à distância a ser disponibilizado ao mercado. Para tal, ainda em 2023, foram investidos R$ 100.000,00 para a estruturação do referido curso. Além disso, foram estimadas despesas e receitas anuais conforme dados apresentados na sequência: Ano Receitas Despesas 2024 R$ 50.000,00 R$ 35.000,00 2025 R$ 65.000,00 R$ 30.000,00 2026 R$ 80.000,00 R$ 30.000,00 2027 R$ 90.000,00 R$ 20.000,00 2028 R$ 90.000,00 R$ 20.000,00 Considerando as informações apresentadas, é possível determinar que o payback simples ocorreu em","options":["2025.","2026.","2027.","2028."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q5","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":5,"subject":"Noções de Direito e Legislação","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 5\n\nAvalie se os princípios da Administração Pública incluem: I. a legalidade; II. a moralidade; III. a livre concorrência; IV. a publicidade. São de fato princípios da Administração Pública os itens","options":["I e II, apenas.","II, III e IV, apenas.","I, II e IV, apenas.","I, II, III e IV."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q6","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":6,"subject":"Noções de Direito e Legislação","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 6\n\nEntre as limitações ao poder de tributar, previstas na Constituição Federal de 1988, estão os princípios gerais do Direito Tributário que, além de estabelecer limites ao poder de tributar, garantem segurança jurídica e justiça fiscal. Sobre esse tema, assinale a afirmativa correta.","options":["O princípio da anterioridade nonagesimal ou noventena estabelece que nenhum tributo pode ser cobrado antes de decorridos 90 dias da data da publicação da sua instituição ou majoração, exce to as contribuições sociais, que podem ser exigidas imediatamente.","O princípio da legalidade tributária determina que nenhum tributo pode ser instituído ou majorado sem previsão em lei complementar.","O princípio da isonomia garante tratamento igualitário a todos que se encontram em situação equivalente, sendo proibida qualquer distinção em razão de ocupação profissional ou função por eles exercida, independentemente da denominação jurídica dos rendimentos, títulos ou direitos.","O princípio da irre troatividade veda a aplicação da lei a ato ou fato pretérito, ainda que a lei seja expressamente interpretativa."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q7","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":7,"subject":"Noções de Direito e Legislação","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 7\n\nA empresa Alfa Indústria Ltda. realizou, ao final do mês de julho, o levantamento de suas obrigações tributárias, verificando os seguintes tributos devidos: • ICMS (Imposto sobre Circulação de Mercadorias e Serviços): incidente sobre as operações de vendas realizadas no período. • ISS (Imposto sobre Serviços): devido pelos serviços prestados. • IRPJ (Imposto sobre a Renda das Pessoas Jurídicas): apurado sobre a renda tributável do exercício. Com base nessas informações, a contabilidade da empresa elaborou um demonstrativo das obrigações tributárias a pagar. De acordo com os conceitos de obrigação tributária e tributo, assinale a afirmativa correta.","options":["O ISS e o ICMS são impostos de mesma competência tributária, pois ambos são devidos aos Estados.","A obrigação tributária principal consiste no pagamento do tributo devido, enquanto a obrigação tributária acessória está relacionada a deveres instrumentais, como a emissão de notas fiscais e declarações ao Fisco.","O IRPJ, por ser um imposto sobre a renda, é classificado como um tributo indireto, pois seu ônus pode ser repassado ao consumidor.","O fato gerador do ICMS ocorre quando a empresa apura seus lucros ao final do exercício contábil."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q8","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":8,"subject":"Ética Profissional","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 8\n\nDe acordo com o CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR em seu item 3: “Este código de ética profissional do contador se aplica também ao _____, no exercício de suas prerrogativas profissionais.” A lacuna fica corretamente preenchida por","options":["empresário contábil.","técnico em contabilidade.","administrador de empresas.","gestor financeiro."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q9","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":9,"subject":"Ética Profissional","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 9\n\nA NBC PG 01 tem por objetivo fixar a conduta do contador, quando no exercício da sua atividade e nos assuntos relacionados à profissão e à classe. Com base na NBC PG 01 é correto afirmar que o contador pode","options":["se utilizar de posição ocupada em entidades de classe para benefício próprio ou para proveito pessoal.","fazer afirmações desproporcionais sobre os serviços que oferece, sua capacitação ou sobre a experiência que possui.","se apropriar de trabalhos, iniciativas ou de soluções encontradas por colegas, que deles não tenha participado, apresentando-os como próprios.","indicar, em qualquer modalidade ou veículo de comunicação, os títulos, as especializações, os serviços oferecidos, os trabalhos realizados e a relação de clientes, quando ela for autorizada por eles."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q10","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":10,"subject":"Teoria da Contabilidade","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 10\n\nPara que um passivo se qualifique para reconhecimento, é necessário haver não somente uma obrigação presente, mas também a probabilidade de saída de recursos que incorporem benefícios econômicos para liquidar essa obrigação. No caso de uma Provisão, o reconhecimento se dá quando: (a) a entidade tem uma obrigação presente (legal ou não formalizada) como resultado de evento passado; (b) seja provável uma necessária saída de recursos que incorporem benefícios econômicos para liquidar a obrigação; e (c) possa ser feita uma estimativa confiável do valor da obrigação. Se essas condições não forem satisfeitas, nenhuma provisão deve ser reconhecida. Em relação ao reconhecimento de um PASSIVO CONTINGENTE, de acordo com a NBC TG 25 (R2), é correto afirmar que","options":["não é reconhecido e nem divulgado em notas explicativas.","não é reconhecido, mas é divulgado em notas explicativas.","é reconhecido e divulgado em notas explicativas.","é reconhecido, mas não é divulgado em notas explicativas."],"answer":null,"officialAnswer":"Anulada","annulled":true,"explanation":"Questão anulada no gabarito definitivo da FGV; não pontua.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q11","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":11,"subject":"Teoria da Contabilidade","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 11\n\nUm supermercado funciona na região sul do país. Em maio de 2024, devido às fortes chuvas, o supermercado perdeu todo o seu estoque. Nas demonstrações contábeis mensais, em 31/05/24, o supermercado optou por baixar todo o estoque, mesmo sem ter recebido um laudo oficial, de modo a tornar as demonstrações mais úteis aos tomadores de decisões. A informação apresenta a seguinte característica qualitativa:","options":["neutralidade.","materialidade.","verificabilidade.","tempestividade."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q12","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":12,"subject":"Teoria da Contabilidade","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 12\n\nDe acordo com a NBC TG Estrutura Conceitual - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO , as demonstrações contábeis consolidadas fornecem informações sobre os ativos, passivos, patrimônio líquido, receitas e despesas","options":["apenas das controladas.","apenas da controladora.","da controladora e de suas controladas, como entidades independentes.","da controladora e de suas controladas, como uma única entidade que reporta."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q13","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":13,"subject":"Teoria da Contabilidade","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 13\n\nDe acordo com a NBC TG Estrutura Conceitual - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, patrimônio líquido é a participação nos ativos da entidade após","options":["a dedução de seus passivos.","a dedução de suas despesas.","o acréscimo de suas receitas.","o acréscimo de seus passivos."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q14","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":14,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 14\n\nSegundo a NBC TG ESTRUTURA CONCEITUAL, para a representação dos relatórios financeiros ser fidedigna ela precisa ser","options":["completa, neutra e isenta de erros.","confiável, tempestiva e com erros mínimos.","tempestiva, útil e comparável.","consistente, completa e compreensível."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q15","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":15,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 15\n\nSegundo a NBC TG 26 (R5) - APRESENTAÇÃO DAS DEMONSTRAÇÕES CONTÁBEIS, quando da elaboração de demonstrações contábeis, a administração deve avaliar a capacidade de a entidade continuar em operação no futuro previsível, o que significa que as demonstrações contábeis devem ser elaboradas no pressuposto da","options":["continuidade, a menos que a administração tenha a intenção de liquidar a entidade ou cessar seus negócios, ou ainda não possua uma alternativa realista senão a descontinuidade de suas atividades.","competência, sendo os itens reconhecidos como ativos, passivos, patrimônio líquido, receitas e despesas, inclusive para a demonstração de fluxo de caixa.","materialidade e agregação, tendo a entidade que apresentar conjun tamente nas demonstrações contábeis cada classe material de itens semelhantes, aglutinando os de natureza ou função distinta mesmo que sejam materiais.","compensação de valores, ativos e passivos ou receitas e despesas devem ser compensados, exceto quand o permitido exclusivamente por norma."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q16","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":16,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 16\n\nSobre a classificação e mensuração de ativos não circulantes mantidos para a venda, de acordo com a NBC TG 31 (R4) - ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA, analise as seguintes afirmativas: I. Os ativos não circulantes mantidos para a venda, desde que satisfeitos os critérios de classificação, são realocados para o ativo circulante da entidade. II. A classificação, a apresentação e a mensuração requeridas pela NBC TG 31 aplicáveis a ativo não circulante classificado como mantido para venda também se aplicam a ativo não circulante que seja classificado como destinado a ser distribuído aos sócios na sua condição de proprietários. III. O ativo não circulante mantido para ven da será mensurado pelo maior entre o seu valor contábil e o valor justo menos as despesas de venda. Está correto o que se afirma em","options":["I, somente.","I e II, somente.","I, II e III.","II, somente."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q17","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":17,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 17\n\nA NBC TG ESTRUTURA CONCEITUAL descreve uma série de conceitos utilizados para a elaboração de relatórios financeiros para fins gerais. Relacione cada elemento a seguir com sua correta definição segundo a Estrutura Conceitual. Elemento Definição a. Despesa b. Patrimônio Líquido c. Receita I. Aumentos nos ativos, ou reduções nos passivos, que resultam em aumento no patrimônio líquido. II. Reduções nos ativos, ou aumentos nos passivos, que resultam em reduções no patrimônio líquido. III. Participação residual nos ativos da entidade após a dedução de todos os seus passivos. Os elementos a, b e c correspondem, respectivamente, às definições","options":["II – III – I.","I – III – II.","II – I – III.","I – II – III."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q18","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":18,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 18\n\nDe acordo com a NBC TG 25 (R2) - PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, provisão é um passivo de prazo incerto ou de valor incerto. Considere que a sociedade empresária Beta tenha recebido laudo de seu advogado sobre um provável pagamento de processo trabalhista, entretanto com mensuração ainda não confiável. Nesse caso, o seu reconhecimento nas demonstrações financeiras deve ser","options":["como apropriação por competência no balanço patrimonial.","como provisão trabalhista no balanço patrimonial.","não realizar reconhecimento de provisão trabalhista no balanço patrimonial e não divulgar em nota explicativa.","não realizar reconhecimento de provisão trabalhista no balanço patrimonial, mas divulgar em nota explicativa como passivo contingente."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q19","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":19,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 19\n\nDe acordo com a NBC TG 09 (R1) - DEMONSTRAÇÃO DO VALOR ADICIONADO, a referida Demonstração (DVA) está relacionada com informações econômicas e com a comunicação de elementos ambientais, sociais e de governança (ASG), e tem por finalidade evidenciar a riqueza criada pela entidade e sua distribuição, durante determinado período. Nesse sentido, considerando que a sociedade empresária “B” possui reversão de perdas estimadas com créditos de liquidação duvidosa, essa informação deve ser apresentada, em sua DVA, do seguinte modo:","options":["em remuneração de capitais próprios, na segunda parte da DVA.","em remuneração de capitais de terceiros, na segunda parte da DVA.","em valor adicionado recebido em transferência, na primeira parte da DVA.","em riqueza criada pela própria entidade, na primeira parte da DVA."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q20","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":20,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 20\n\nA Demonstração do Valor Adicionado proporciona aos usuários das demonstrações contábeis informações relativas à riqueza criada pela entidade em determinado período e à forma como tais riquezas foram distribuídas. Na distribuição do valor adicionado, o total de “Remuneração de capitais próprios” deve ser igual","options":["às reservas de lucro reportadas no Balanço Patrimonial.","ao pagamento de dividendos reportado na Demonstração dos Fluxos de Caixa.","ao resultado líquido do exercício reportado na Demonstração do Resultado do Período.","à distribuição de dividendos reportada na Demonstração das Mutações do Patrimônio Líquido."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q21","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":21,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 21\n\nUma loja que vende produtos de escritório apresentava os seguintes saldos em 31/12/2023: • Custo da mercadoria vendida (inclui os valores dos impostos recuperáveis): R$ 80.000,00 • Despesa de depreciação dos ativos imobilizados: R$ 15.000,00 • Perdas estimadas com crédito de liquidação duvidosa: R$ 6.000,00 • Perdas por desvalorização dos ativos imobilizados: R$ 10.000,00 • Receita de contrato com clientes: R$ 200.000,00 Assinale a opção que indica o saldo do valor adicionado líq uido produzido pela loja, apresentado em sua Demonstração do Valor Adicionado em 31/12/2023.","options":["R$ 89.000,00.","R$ 114.000,00.","R$ 104.000,00.","R$ 194.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q22","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":22,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 22\n\nDe acordo com a NBC TG 25 (R2) - PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, a entidade deve divulgar, em notas explicativas, para cada classe de passivo contingente na data do balanço, uma breve descrição da natureza do passivo contingente, a menos que a possibilidade de ocorrer qualquer desembolso na liquidação seja","options":["remota.","possível.","provável.","possível e provável."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q23","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":23,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 23\n\nA sociedade empresária Solar administra a carreira de influenciadores digitais. As empresas i nteressadas em divulgar o seu produto ou serviço por meio dos influenciadores devem pagar para a Solar R$ 20.000,00 por um pacote que consiste em oito inserções em redes socias, sendo quatro ao mês. Em 01/05/2024, a Cia Yellow assinou contrato e pagou, à vista, R$ 20.000,00 para a Cia Solar. Foram realizadas quatro inserções em junho e quatro em julho. A Cia Yellow estimou que, por conta da divulgação, o seu faturamento aumentou em R$ 15.000,00 em agosto e em R$ 18.000,00 em setembro. De acordo com o Regime de Competência, a despesa com a divulgação deve ser reconhecida pela Cia Yellow do seguinte modo:","options":["R$ 20.000,00 em maio.","R$ 10.000,00 em junho e R$ 10.000,00 em julho.","R$ 10.000,00 em agosto e R$ 10.000,00 em setembro.","R$ 5.000,00 em cada um dos meses de junho a setembro."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q24","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":24,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 24\n\nEm 01/09/2024, uma sociedade empresária localizada em Belo Horizonte adquiriu aparelhos de informática de Manaus por R$ 40.000,00. O frete para a entrega por caminhão era de R$ 2.000,00. No entanto, para receber os aparelhos mais rápido, a sociedade empresária solicitou a entrega por avião e pagou o valor de R$ 5.500,00 pelo frete. A instalação dos aparelhos no escritório custou R$ 1.000,00. Ainda, foram gastos R$ 2.000,00 com testes para verificar se os aparelhos estavam funcionando corretamente. O valor dos aparelhos de informática a serem registrados no ativo imobilizado da sociedade empresária é de","options":["R$ 43.000,00.","R$ 45.000,00.","R$ 46.500,00.","R$ 48.500,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q25","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":25,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 25\n\nEm janeiro de 2025, um artista, que possui uma empresa, estava em um evento estratégico em um resort na Bahia. Ao voltar da viagem, descobriu que um influenciador digital, que também estava no evento, divulgou fotos e vídeos do artista em redes sociais. A empresa do artista entrou na justiça por quebra de privacidade contra o resort e contra o influencia dor, pedindo, respectivamente, R$ 10.000,00 e R$ 15.000,00. Os advogados da empresa do artista julgaram que as chances de ganho das causas eram, respectivamente, remota e possível. Com base no julgamento dos advogados, a empresa deve apresentar, em suas demonstrações contábeis, um ativo contingente","options":["igual a zero.","de R$ 10.000,00.","de R$ 15.000,00.","de R$ 25.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q26","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":26,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 26\n\nA Cia Lua atua no setor de comércio de relógios e tem 20 empregados. Todos os anos, na primeira semana de janeiro, a empresa contrata uma equipe de médicos para ir ao escritório realizar exames de rotina em seus empregados. Em janeiro de 2025, os gastos com os médicos foram de R$ 6.000,00. Do valor, 20% são pagos pelos empregados, enquanto o restante é pago pela empresa. O impacto do atendimento médico na Demonstração do Resultado da Cia Lua em janeiro de 2025, de acordo com o Regime de Competência, foi de","options":["-R$ 400,00.","-R$ 500,00.","-R$ 4.800,00.","-R$ 6.000,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q27","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":27,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 27\n\nEm fevereiro de 2025, um hotel adquiriu um televisor de 98 polegadas para que os seus hospedes assistissem a cerimônia do Oscar, em março. O preço do televisor era de R$ 40.000,00. Na data da compra foi acordado com o fornecedor que o pagamento seria realizad o por Pix e, em decorrência, o hotel obteve uma redução de 5% sobre o preço original. Assinale a opção que indica a contrapartida da diminuição de R$ 38.000,00 na conta “Disponibilidades”, nas demonstrações contábeis do hotel.","options":["Ativo imobilizado de R$ 38.000,00.","Ativo imobilizado de R$ 40.000,00 e receita financeira de R$ 2.000,00.","Ativo imobilizado de R$ 40.000,00 e outras receitas de R$ 2.000,00.","Ativo imobilizado de R$ 40.000,00 e retificação do ativo imobilizado de R$ 2.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q28","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":28,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 28\n\nUma empresa de doces e bolos possui em 31/12/X0 os seguintes saldos em seu Balanço Patrimonial: • Caixa e equivalentes de caixa: R$ 100.000,00; • Empréstimos a pagar de curto prazo: R$ 250.000,00; • Financiamentos a pagar de longo prazo: R$ 330.000,00; • Imobilizado: R$ 450.000,00; • Intangível: R$ 320.000,00; • Estoques: R$ 250.000,00; • Capital Social: R$ 540.000,00. Com base nesses saldos, o valor do ativo não circulante da empresa é","options":["R$ 770.000,00.","R$ 350.000,00.","R$ 1.020.000,00.","R$ 450.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q29","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":29,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 29\n\nA empresa ABC S.A. comprou materiais, em agosto de X1, com a finalidade de utilizá -los em suas atividades. O pagamento foi realizado em novembro de X1, e os materiais foram utilizados na prestação de serviços em setembro de X1. Esses materiais devem ser reconhecidos como despesa no mês de","options":["novembro de X1.","setembro de X1.","agosto de X1.","dezembro de X1."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q30","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":30,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 30\n\nRelacione as contas contábeis do balanço patrimonial apresentadas a seguir com seus respectivas grupos contábeis. 1. Empréstimos a pagar após 12 meses. 2. Contas a receber em 5 meses. 3. Contas a pagar em 3 meses. 4. Imóveis para uso por 10 anos. ( ) Ativo Circulante. ( ) Ativo Não Circulante. ( ) Passivo Circulante. ( ) Passivo Não Circulante. A relação correta, na ordem apresentada, é","options":["4 – 2 – 1 – 3.","2 – 4 – 3 – 1.","3 – 1 – 2 – 4.","1 – 3 – 4 – 2."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q31","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":31,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 31\n\nAssinale a opção que contempla apenas componentes do Patrimônio Líquido, descritos na Lei nº 6.404/76 e alterações posteriores.","options":["Capital Social – Investimentos – Ações em Tesouraria.","Capital Social – Dividendos Obrigatórios a Pagar – Ajustes de Avaliação Patrimonial.","Reservas de Capital – Reservas de Lucros – Ações em Tesouraria.","Ajustes de Avaliação Patrimonial – Capital Social – Debêntures."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q32","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":32,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 32\n\nA companhia investidora Alfa S.A., obrigada legalmente a elaborar demonstrações financeiras consolidadas, possui a seguinte participação societária nas empresas: Investida % de participação de Alfa S.A. PL da investida em 31/12/2023 Kappa (controlada) 90 R$ 1.000.000,00 Sigma (controlada) 70 R$ 700.000,00 Zeta (coligada) 25 R$ 600.000,00 Delta (sem influência significativa) 15 R$ 900.000,00 Com base exclusivamente nas informações acima, o montante registrado na conta de participação de acionistas não controladores no balanço consolidado da investidora Alfa S.A. em 31/12/2023 deverá ser de","options":["R$ 100.000,00.","R$ 310.000,00.","R$ 760.000,00.","R$ 1.525.000,00."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q33","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":33,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 33\n\nUma empresa adquiriu uma máquina e registrou na contabilidade os seguintes dispêndios: • Preço de aquisição: R$ 500.000,00; • Imposto de importação: R$ 50.000,00 (não recuperável); • Preparação do local: R$ 100.000,00; • Custo com materiais consumido na realização de testes de funcionamento: R$ 50.000,00; • Honorários dos técnicos que realizaram os testes: R$ 60.000,00; • Vida útil estimada: 10 anos; • Valor residual: R$ 100.000,00. De acordo com a NBC TG 27 (R4) - ATIVO IMOBILIZADO, o custo da máquina, ou seja, o valor contábil de registro inicial desse imobilizado, será de","options":["R$ 500.000,00.","R$ 550.000,00.","R$ 650.000,00.","R$ 760.000,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q34","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":34,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 34\n\nUma empresa adquiriu uma máquina em 01/01/2020 pelo custo total de R$ 240.000,00. No registro inicial da máquina no imobilizado, a empresa estimou a vida útil da máquina em 8 anos, sem valor residual. Na data da aquisição, a empresa iniciou a depreciação pelo método linear. Em 31/12/2024, a empresa reavaliou a vida útil para 10 anos, aumentando em 2 anos a vida útil inicialmente estimada. Além disso, verificou que o valor residual da máquina passou a ser de R$ 40.000,00. Com base exclusivamente nos dados acima apresentados, o valor anual da despesa de depreciação a ser contabilizada a partir das alterações ocorridas em 31/12/2024 deve ser de","options":["R$ 40.000,00.","R$ 30.000,00.","R$ 18.000,00.","R$ 10.000,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q35","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":35,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 35\n\nA Indústria Cadeiras Maceió Ltda. produz e comercializa cadeiras de escritório. No mês de setembro de X4, a empresa produziu 30.000 cadeiras e não possuía estoque inicial. No mês, vendeu 24.000 unidades a um preço unitário de R$ 100,00. Os custos variáveis totais, incluindo matéria -prima, mão de obra direta e outros custos variáveis, somaram R$ 1.800.000,00. Os custos fixos, compostos principalmente por aluguel da fábrica, depreciação do m aquinário e salários fixos dos supervisores da produção, totalizaram R$ 200.000,00. As despesas fixas, como gastos com administração e vendas, somaram R$ 100.000,00. Com base nessas informações, o lucro obtido com as vendas, aplicando o método de custeio v ariável, foi de","options":["R$ 660.000,00.","R$ 960.000,00.","R$ 700.000,00.","R$ 300.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q36","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":36,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 36\n\nEm janeiro de 2024, uma fábrica que produz bolas de futebol incorreu nos seguintes gastos: aluguel do imóvel e das máquinas: R$ 30.000,00; embalagens indispensáveis ao produto final: R$ 2.000,00; matéria -prima: R$ 10.000,00; seguro do imóvel: R$ 5.000,00. Assinale a opção que indica os custos fixos da fábrica no mês.","options":["R$ 5.000,00.","R$ 30.000,00.","R$ 35.000,00.","R$ 45.000,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q37","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":37,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 37\n\nLeia o fragmento a seguir: “Departamento é a unidade _____ administrativa para a Contabilidade de Custos, representada, na maioria dos casos, por pessoas e máquinas, em que se desenvolvem atividades _____.” Assinale a opção cujos itens completam corretamente as lacunas do fragmento.","options":["padrão – heterogêneas","mínima – homogêneas","máxima – complementares","padrão – complementares"],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q38","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":38,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 38\n\nGasto pode ser definido como o sacrifício financeiro necessário para obter um produto ou serviço, representado pela entrega ou promessa de entrega de ativos. Assim, custos, despesas, investimentos e desembolsos são tipos de gastos. Em relação ao tema, analise as afirmativas a seguir. I. Custo é um gasto diretamente relacionado a um bem ou serviço utilizado na produção de outros bens e serviços. II. Despesa é um gasto com bens ou serviços consumidos direta ou indiretamente para obtenção de receitas. III. Investimento é um gasto que se tornou um item do patrimônio líquido em função da expectativa de geração futura de caixa para a entidade ou em função de sua vida útil. IV. Desembolso é um gasto que ocorre quando bens ou serviços são consumidos de forma anormal e/ou involuntária que afetam diretamente o resultado da entidade. Estão corretas as afirmativas","options":["III e IV, apenas.","I, II e III, apenas.","I e II, apenas.","II, III e IV, apenas."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q39","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":39,"subject":"Contabilidade Gerencial","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 39\n\nEm 01/01/2024, uma loja de teclados apresentava os seguintes saldos em seu balanço patrimonial: • Disponibilidades: R$ 60.000,00; • Estoque: R$ 240.000,00; • Patrimônio Líquido: R$ 300.000,00. O estoque era composto por 400 unidades de teclado, sendo que cada uma era vendida por R$ 1.000,00. No primeiro semestre de 2024, os gastos fixos, considerando a loja e o escritório, foram os seguintes: • Aluguel: R$ 36.000,00; • Depreciação: R$ 30.000,00; • Salários: R$ 60.000,00. Além disso, foi paga, antecipadamente, uma despesa de R$ 4.000,00 relacionada ao segundo semestre do ano. O ponto de equilíbrio contábil da loja, em unidades, no primeiro semestre de 2024, foi de","options":["240.","300.","315.","375."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q40","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":40,"subject":"Contabilidade Gerencial","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 40\n\nAcerca do Modelo de Determinação do Preço de Transferência, av alie as afirmativas a seguir. I. No Modelo de Preço de Transferência Baseado em Custo Total Realizado (Full Cost), o bem/serviço é transferido pelo valor resultante do somatório dos custos totais incorridos (fixos e variáveis) dividido pelo volume de produção de um determinado período (custeio por absorção). II. No Modelo de Preço de Transferência Baseado em Negociação entre os Gestores, o bem/serviço é transferido pelo preço vigente no mercado, que pode ser um preço médio. III. No Modelo de Preço de Transferência Baseado em Custo de Oportunidade, o preço do bem/serviço transferido estrutura - se a partir da premissa de que deveria refletir o valor do benefício possível de ser auferido na melhor alternativa econômica de obtenção dos insumos demandados. Está correto o que se afirma em","options":["I, apenas.","I e II, apenas.","I e III, apenas.","I, II e III."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q41","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":41,"subject":"Contabilidade Gerencial","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 41\n\nAnalise as contas do Balanço Patrimonial a seguir: ATIVO 2023 PASSIVO 2023 Caixa R$ 5.000,00 Fornecedores R$ 15.000,00 Aplicações financeiras R$ 10.000,00 Impostos a pagar R$ 5.000,00 Contas a receber R$ 15.000,00 Empréstimos de curto prazo R$ 10.000,00 Estoques R$ 30.000,00 Empréstimos de longo prazo R$ 20.000,00 Imobilizado R$ 10.000,00 Patrimônio líquido R$ 80.000,00 Intangível R$ 50.000,00 Investimentos R$ 10.000,00 TOTAL R$ 130.000,00 TOTAL R$ 130.000,00 O Índice de Liquidez Seca e o Índice de Liquidez Corrente são, respectivamente, iguais a","options":["2,00 e 1,00.","1,00 e 2,00.","1,00 e 2,60.","2,00 e 0,75."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q42","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":42,"subject":"Contabilidade Aplicada ao Setor Público","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 42\n\nA Lei Orçamentária Anual de cada ente federado deverá conter todas as receitas e despesas de todos os Poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público. Esse princípio orçamentário é denominado","options":["Unidade.","Universalidade.","Exclusividade.","Orçamento Bruto."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q43","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":43,"subject":"Contabilidade Aplicada ao Setor Público","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 43\n\nDe acordo com a NBC TSP ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA ELABORAÇÃO E DIVULGAÇÃO DE INFORMAÇÃO CONTÁBIL DE PROPÓSITO GERAL PELAS ENTIDADES DO SETOR PÚBLICO, as informações financeiras e não financeiras são relevantes quando","options":["permitem que os usuários compreendam o seu significado.","retratam a substância da transação, a qual pode não corresponder, necessariamente, à sua forma jurídica.","são capazes de influenciar significativamente o cumprimento dos objetivos da elaboração e da divulgação da informação contábil.","estão disponíveis aos usuários a tempo de serem úteis para fins de prestação de contas, responsabilização e tomada de decisão."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q44","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":44,"subject":"Contabilidade Aplicada ao Setor Público","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 44\n\nCom relação aos usuários dos Relatórios Contábeis de Propósito Geral das Entidades do Setor Público (RCPGs) , aval ie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Os RCPGs devem ser elaborados e divulgados, principalmente, para atender às necessidades de informações dos usuários dos serviços e dos provedores de recursos, quando est es detêm a prerrogativa de exigir que a entidade do setor público divulgue as informações que atendam às suas necessidades específicas. ( ) Os membros do Poder Legislativo são também usuários primários dos RCPGs e utilizam extensiva e continuamente os relatórios enquanto atuam como representantes dos interesses dos usuários de serviços e dos provedores de recursos. ( ) Alguns usuários dos serviços e alguns provedores de recursos que dependem dos RCPGs para obter informações que eles necessitam para os propósitos de prestação de contas e responsabilização e tomada de decisão podem não ser cidadãos, como, agências bilaterais ou multilaterais. De acordo com a NBC TSP ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA ELABORAÇÃO E DIVULGAÇÃO DE INFORMAÇÃO CONTÁBIL DE PROPÓSITO GERAL PELAS ENTIDADES DO SETOR PÚBLICO as afirmativas são, respectivamente,","options":["V – F – F.","V – F – V.","F – V – V.","V – V – F."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q45","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":45,"subject":"Controladoria","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 45\n\nEm 2022, uma entidade tinha o seu desempenho financeiro analisado com base no Retorno sobre o Investimento. Em 2023, a administração da entidade determinou que o seu desempenho passasse a ser avaliado com base no EVA (Valor Econômico Agregado). Uma vantagem dessa substituição é a incorporação, na avaliação,","options":["do custo de oportunidade.","das receitas operacionais.","das despesas operacionais.","das receitas financeiras."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q46","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":46,"subject":"Controladoria","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 46\n\nA Administração de uma empresa, na elaboração de seu plano estratégico, deve, na medida do possível, observar alguns aspectos de formalidade necessários dado a sua relevância e seu impacto nas operações da empresa. A respeito desse tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O Plano Estratégico deve ser executado pela Controladoria sob o comando da alta administração da empresa. ( ) Uma vez elaborado e aprovado, o Plano Estratégico não deve ser alterado ou ajustado. ( ) Planejamento Estratégico é a atividade que se ocupa da implementação do Plano Estratégico e assegura que os recursos necessários foram obtidos e também que estão sendo usados de maneira eficiente. ( ) A elaboração de um Planejamento Estratégico deve levar em consideração que todas as decisões são interdependentes, sejam el as simples ou complexas. Assim, um dos principais desafios dessa atividade é um ajustamento dessa cadeia sistêmica de decisões e a avaliação de suas consequências. As afirmativas são, respectivamente,","options":["F – V – V – F.","F – V – F – V.","V – F – F – V.","V – F – V – F."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q47","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":47,"subject":"Auditoria","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 47\n\nUma empresa de auditoria independente precisou contratar o trabalho de um especialista na área de Tecnologia da Informação. Após receber as conclusões do especialista, foi constatado que esse trabalho era adequado para fins da auditoria. Com base na NBC T A 620 – UTILIZAÇÃO DO TRABALHO DE ESPECIALISTAS, assinale a afirmativa correta acerca da responsabilidade do auditor ao emitir a sua opinião.","options":["O auditor tem sua responsabilidade dividida com o especialista em todo o trabalho.","O auditor é o único res ponsável por expressar opinião de auditoria, e essa responsabilidade não é reduzida pelo trabalho de especialista contratado pelo auditor.","O auditor é responsável pela parte contábil, e o especialista, pelo trabalho que fez.","O auditor, modificando sua opinião em virtude do trabalho do especialista, não terá nenhuma responsabilidade, sendo a responsabilidade transferida ao especialista."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q48","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":48,"subject":"Auditoria","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 48\n\nNo exercício de 2024, uma sociedade empresária foi incluída em um Plano de Refina nciamento de Impostos. O fato foi apropriadamente divulgado nas demonstrações contábeis. Mesmo sendo divulgado o Plano de Refinanciamento de Impostos, o auditor julgou que o assunto é de importância fundamental para o entendimento pelos usuários das demons trações contábeis. Assim, o auditor independente incluirá, em seu relatório,","options":["uma ressalva.","um fato relevante.","um parágrafo de ênfase.","um parágrafo de outros assuntos."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q49","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":49,"subject":"Perícia Contábil","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 49\n\nJulgue as afirmativas a seguir, com base na NBC TP 01 (R1) - PERÍCIA CONTÁBIL. I. Concluídos os trabalhos periciais, o perito nomeado deve apresentar laudo pericial contábil, e o assistente técnico deve oferecer seu parecer pericial contábil, obedecendo aos respectivos prazos legais e/ou contratuais. II. O assistente técnico não pode validar o laudo pericial quando o documento tiver sido elaborado por leigo ou profissional de outra área, devendo, nesse caso, oferecer o parecer pericial contábil sobre a matéria perici ada. III. Mesmo quando assinado em conjunto por peritos, a responsabilidade acerca do laudo pericial contábil é exclusiva do perito nomeado, não sendo passível a assunção de responsabilidade solidária pelos demais peritos assinantes no documento. IV. As respostas aos quesitos devem ser objetivas, completas e não lacônicas. Estão corretas as afirmativas","options":["III e IV, apenas.","I e II, apenas.","I e III, apenas.","II e IV, apenas."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.1-tipo1-q50","examId":"2025.1-tipo1","examLabel":"2025.1 — Tipo 1","number":50,"subject":"Perícia Contábil","source":"Exame de Suficiência 2025.1 — Tipo 1; gabarito definitivo FGV","text":"Questão 50\n\nA Norma Brasileira de Contabilidade Profissional – Perito (NBC PP 01) estabelece as diretrizes e os requisitos para a atuação dos contadores como peritos, incluindo qualificações, deveres, responsabilidades, normas de conduta e as situações que podem acarretar impedimento ou suspeição. Analise as afirmativas a seguir, com base na NBC PP 01, e assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) Em casos de impedimento ou suspeição, o perito contábil tem a opção de continuar no caso desde que obtenha o consentimento expresso de todas as partes envolvidas e da autoridade competente. ( ) A NBC PP 01 permite que o perito utilize documentos externos aos autos processuais como elementos de prova, desde que previamente acordado com as partes e autorizado pelo juiz ou autoridade compe tente. ( ) O perito contábil deve elaborar a proposta de honorários periciais considerando não apenas os custos e o tempo necessário para a execução dos trabalhos, mas também levando em conta a relevância e o risco envolvidos no objeto da perícia. As afirmativas são, respectivamente,","options":["F – F – V.","V – F – F.","F – V – F.","V – V – V. Realização"],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q1","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":1,"subject":"Português","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 1\n\nOs dicionários registram os diversos significados de um vocábulo; os dois textos abaixo definem o termo “contabilidade”, segundo, respectivamente, os dicionários de Antônio Houaiss (AH) e de Aurélio Buarque de Hollanda (ABH). (AH) Contabilidade: ciência teórica e prática que estuda os métodos de cálculo e registro da movimentação financeira de uma firma ou empresa. (ABH) Contabilidade: ciência que estuda e interpreta os registros dos fenômenos que afetam o patrimônio de uma entidade (empresa, instituição pública, pessoa física, instituição não lucrativa etc.) . Sobre esses textos, assinale a afirmativa correta.","options":["As definições começam sempre por uma palavra de conteúdo geral que, nesses casos, é representada pela palavra “ciência”.","Os termos “teórica e prática” e “cálculo e registro” são construídos com palavras antônimas, ou seja, de significados opostos.","Os termos entre parênteses da segunda definição mostram todos os tipos de entidades referidas na definição.","As duas definições mostram o mesmo objetivo da ciência “contabilidade”."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q2","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":2,"subject":"Português","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 2\n\nAs frases listadas nas opções a seguir foram reescritas de forma a eliminar -se o “que”, com substituição do verbo por um substantivo semanticamente correlato. Assinale a frase em que a substituição foi feita de forma adequada.","options":["Cabral, que descobriu o Brasil, merece homenagens. / Cabral, o criador do Brasil, merece homenagens.","Caminha, que escreveu a carta, registrou o fato. / Caminha, o redator da carta, regi strou o fato.","As caravelas, que atravessaram o oceano, resistiram a tempestades. / As caravelas, navegadoras do oceano, resistiram a tempestades.","A descoberta do Brasil, que ocorreu em 1500, ficou na história. / A descoberta do Brasil, ocorrente em 1500, ficou na história."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q3","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":3,"subject":"Matemática Financeira e Estatística","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 3\n\nA empresa Gama S.A. avalia um projeto com investimento inicial de R$ 300.000,00, a ser realizado na data zero. Estimam -se entradas de caixa ao final de cada ano, conforme segue: • 1º ano: R$ 121.000,00; • 2º ano: R$ 121.000,00; • 3º ano em diante: R$ 146.410,00 por ano. Chama-se payback descontado ao tempo necessário para que a soma dos fluxos de caixa descontados iguale o investimento inicial. Considerando-se uma taxa de desconto de 10% ao ano, o payback do projeto está entre","options":["1 ano e 2 anos.","2 anos e 3 anos.","3 anos e 4 anos.","4 anos e 5 anos."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q4","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":4,"subject":"Matemática Financeira e Estatística","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 4\n\nA empresa VGF S.A. tomou um empréstimo bancário de R$ 14.560,00 para financiar a compra de equipamentos. O contrato de empréstimo estabelece que o valor tomado deve ser liquidado por meio de uma série postecipada de 3 pagamentos mensais, iguais e sucessivos. O regime de capitalização adotado é o de juros compostos, à taxa de 20% ao mês. Considerando essas informações, é correto afirmar que o valor das prestações mensais será de","options":["R$ 4.853,33.","R$ 6.400,00.","R$ 6.912,00.","R$ 7.280,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q5","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":5,"subject":"Noções de Direito e Legislação","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 5\n\nPara o contador que atua no setor público ou na fiscalização de contratos administrativos, o conhecimento da Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos), é fundamental para a avaliação da legalidade e conformidade dos gastos públicos. O Art. 5º dessa Lei elenca diversos princípios que devem guiar a atuação das Administrações Públicas diretas, autárquicas e fundacionais da União, dos Estados, do Distrito Federal e dos Municípios. Com base no texto legal, avalie os seguintes princípios: I. Impessoalidade; II. Transparência; III. Racionalidade econômica; IV. Probidade administrativa. Estão expressamente listados no Art. 5º da Lei os princípios","options":["I e IV, apenas.","II e III, apenas.","I, II e IV, apenas.","I, II, III e IV."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q6","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":6,"subject":"Noções de Direito e Legislação","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 6\n\nUm estudante de contabilidade, ao iniciar seus estudos em Direito Tributário, depara -se com o conceito fundamental de tributo. Para uma compreensão precisa, ele busca a definição legal contida no Código Tributário Nacional (Lei nº 5.172/1966). De acordo com esse diploma legal, assinale a opção que define corretamente o tributo.","options":["Tributo é toda prestação pecuniária voluntária, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída por meio de medida provisória e cobrada mediante atividade administrativa com alguma discricionariedade.","Tributo é toda sanção de ato ilícito, cobrada compulsoriamente em bens ou serviços, instituída em lei e aplicada com base em decisões discricionárias da administração pública.","Tributo é toda prestação pecuniária compulsória, em bens ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída por qualquer ato normativo e cobrada mediante atividade administrativa parcialmente vinculada.","Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q7","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":7,"subject":"Noções de Direito e Legislação","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 7\n\nDe acordo com a Lei Complementar nº 123, de 14 de dezembro de 2006, que institui o Estatuto Nacional da Microempresa e da Empresa de Pequeno Porte, os limites de receita bruta anual para fins de enquadramento são informações essenciais para a atuação do contador. Considerando o que a lei estabelece sobre a definição de Microempresa (ME) e Empresa de Pequeno Porte (EPP), assinale a afirmativa correta.","options":["Uma Microempresa (ME) aufere, em cada ano -calendário, receita bruta igual ou inferior a R$ 120.000,00, e uma Empresa de Pequeno Porte (EPP) aufere receita bruta superior a R$ 120.000,00 e igual ou inferior a R$ 1.200.000,00.","Uma Microempresa (ME) aufere, em cada ano -calendário, receita bruta igual ou inferior a R$ 360.000,00, e uma Empresa de Pequeno Porte (EPP) aufere receita bruta superior a R$ 360.000,00 e igual ou inferior a R$ 4.800.000,00.","Uma Microempresa (ME) aufere, em cada ano-calendário, receita bruta igual ou inferior a R$ 81.000,00, e uma Empresa de Pequeno Porte (EPP) aufere receita bruta superior a R$ 81.000,00 e igual ou inferior a R$ 4.800.000,00.","Os limites de receita bruta para ME e EPP são fixados anualmente por decreto do Comitê Gestor do Simples Nacional."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q8","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":8,"subject":"Ética Profissional","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 8\n\nUm escritório contábil quer expandir sua clientela com campanha de marketing, mas tem dúvidas sobre publicidade e preços conforme o Código de Ética. Com base na NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR, uma prática de divulgação e precificação eticamente correta é","options":["prometer redução garantida de tributos sem embasamento técnico.","comparar preços e criticar concorrentes.","divulgar clientes e faturamento sem autorização.","expor conhecimento técnico com artigos e estudos de caso."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q9","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":9,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 9\n\nDurante uma reunião com a diretoria de uma empresa cliente, o contador responsável apresentou os impactos financeiros de um novo contrato. Embora os dados estivessem tecnicamente corretos, os gestores demonstraram dúvidas e certa dificuldade em compreender a apresentação. Nesse cenário, a habilidade profissional que contribuiria para que o contador fosse mais eficaz, de acordo com a NBC PG 100 (R1) - CUMPRIMENTO DO CÓDIGO, DOS PRINCÍPIOS FUNDAMENTAIS E DA ESTRUTURA CONCEITUAL, seria","options":["realizar escuta ativa.","demonstrar clareza na exposição de dados.","revisar a legislação aplicável.","ignorar as dúvidas do cliente."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q10","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":10,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 10\n\nDe acordo com a NBC TG ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, as características qualitativas fundamentais são relevância e representação fidedigna, sendo que, para ser representação fidedigna, a representação deve ser completa, neutra e isenta de erros. Uma informação neutra pode","options":["ser parcial.","ser prudente.","possuir inclinações.","ser tendenciosa na seleção de informações financeiras."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q11","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":11,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 11\n\nDe acordo com a NBC TG ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, para ajudar os usuários das demonstrações contábeis a identificar e avaliar mudanças e tendências, as demonstrações contábeis","options":["são elaboradas com base na forma jurídica, em detrimento da essência das trans ações.","restringem a utilização de estimativas a casos em que poderá haver perdas financeiras do usuário.","incluem, apenas, informações que podem ser compreendidas, também, por usuários com pouco conhecimento das atividades comerciais e econômicas, sem auxílio de consultores.","fornecem informações comparativas de, pelo menos, um período de relatório anterior."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q12","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":12,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 12\n\nUma sociedade empresária presta serviços de perícia a terceiros. Em junho de 2024, aconteceram os seguintes fatos: • Compra de material de escritório para pagamento em 60 dias: R$ 5.000,00; • Recebimento antecipado pelos serviços que serão prestados no segundo semestre: R$ 10.000,00; • Reconhecimento do salário de seus empregados, para pagamento em 5 de julho: R$ 12.000,00 . Em junho de 2024, o passivo da sociedade empresária aumentou em","options":["R$ 15.000,00.","R$ 17.000,00.","R$ 22.000,00.","R$ 27.000,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q13","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":13,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 13\n\nDe acordo com a NBC TG ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, com relação às implicações das características qualitativas para a escolha da base de mensuração, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Utilizar consistentemente as mesmas bases de mensuração para os mesmos itens, seja de período a período, na entidade que reporta ou em um único período para diferentes entidades, prejudica a comparabilidade das demonstrações. ( ) A mudança na base de mensuração pode tornar as demonstrações contábeis menos com preensíveis. Contudo, a mudança pode ser justificada se outros fatores compensarem a redução na compreensibilidade, por exemplo, se a mudança resulta em informações mais relevantes. ( ) A verificação é melhorada utilizando -se bases de mensuração que resu ltam em avaliações que podem ser independentemente corroboradas diretamente, por exemplo, observando os preços, ou indiretamente, por exemplo, verificando dados de entrada de modelo. As afirmativas são, respectivamente,","options":["V – V – V.","V – V – F.","V – F – V.","F – V – V."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q14","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":14,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 14\n\nA NBC TG 28 (R4) - PROPRIEDADES PARA INVESTIMENTO trata de definição, classificação e mensuração de propriedades para investimento. Sobre esse item, analise as seguintes afirmativas: I. Propriedade para Investimento é classificada dentro do subgrupo investimento no ativo circulante. II. Propriedade para investimento é um terreno, edifício ou veículo mantido pela entidade para auferir aluguel ou valorização do capital. III. Propriedade para investimento no momento da aquisição deve ser mensurada pelo seu custo. Está correto o que se afirma em","options":["II e III, apenas.","III, apenas.","I, II e III.","II, apenas."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q15","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":15,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 15\n\nUm ativo individual ou um grupo de ativos mantido para venda são ativos a ser alienados, por venda ou de outra forma, em conjunto como um grupo de ativos em uma só transação, e passivos diretamente associados a esses ativos qu e serão transferidos na transação. De acordo com a NBC TG 31 (R4) - ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA , a depreciação do ativo ou grupo de ativos mantidos para venda deve","options":["ser parcial, pois o ativo ou grupo de ativos ainda está operando.","ser mantida até a venda ser concretizada.","ser interrompida quando o ativo ou grupo de ativos for reclassificado como mantido para venda.","continuar como estava antes da reclassificação."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q16","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":16,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 16\n\nDe acordo com a NBC TG 01 (R4) - REDUÇÃO AO VALOR RECUPERÁVEL DE ATIVOS, o valor em uso é o valor presente de fluxos de caixa futuros esperados que devem advir de um ativo ou de unidade geradora de caixa. Avalie se os seguintes elementos devem ser refletidos no cálculo do valor em uso do ativo: I. O valor pago na aquisição do ativo. II. As expectativas acerca de possíveis variações no montante ou no período de ocorrência desses fluxos de caixa futuros. III. As estimativas dos fluxos de caixa futuros que a entidade espera obter com esse ativo. IV. O valor do dinheiro no tempo, representado pela atual taxa de juros livre de risco. Estão corretos os elementos","options":["I, II e III, apenas.","I e II, apenas.","III e IV, apenas.","II, III e IV, apenas."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q17","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":17,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 17\n\nO ágio por expectativa de rentabilidade futura ( goodwill) reconhecido em uma combinação de negócios é um ativo que representa benefícios econômicos futuros advindos de outros ativos adquiridos na combinação de negócios que não são identificados individualmente e não são reconhecidos separadamente. De acordo com a NBC TG 04 (R4) - ATIVO INTANGÍVEL e com a NBC TG 15 (R4) - COMBINAÇÃO DE NEGÓCIOS, a empresa adquirente deve reconhecer, na data da aquisição, separadamente do ágio de rivado da expectativa de rentabilidade futura (goodwill) apurado em uma combinação de negócios, um ativo intangível da adquirida, independentemente de o ativo ter sido reconhecido pela adquirida antes da aquisição da empresa. A perda por desvalorização reconhecida para o ágio por expectativa de rentabilidade futura ( goodwill) não deve ser revertida em período subsequente, pois","options":["não pode ser amortizada.","no plano de contas não há rubrica apropriada.","gera fluxos de caixa, independentemente de outros ativos ou grupos de ativos.","é equivalente ao goodwill gerado internamente."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q18","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":18,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 18\n\nA Demonstração do Valor Adicionado (DVA) busca evidenciar o valor e a distribuição da riqueza econômica gerada pelas atividades da sociedade empresária, incluindo também o valor adicionado recebido em transferência. A riqueza gerada é evidenciada na distri buição entre o capital (Remuneração de capital próprio e de terceiros), trabalho (Pessoal) e governo (Impostos, taxas e contribuições). Relacione cada item a seguir ao respectivo componente da distribuição da riqueza, conforme disposto na NBC TG 09 (R1) - DEMONSTRAÇÃO DO VALOR ADICIONADO. ( ) Fundo de Garantia por Tempo de Serviços (FGTS) ( ) Aluguéis pagos ( ) Dividendos distribuídos ( ) Contribuição Social sobre o Lucro Líquido (CSLL) 1. Pessoal 2. Impostos, taxas e contribuições 3. Remuneração de capital de terceiros 4. Remuneração de capital próprio A relação correta, na ordem apresentada, é","options":["1 – 2 – 3 – 4.","2 – 3 – 4 – 1.","2 – 4 – 3 – 1.","1 – 3 – 4 – 2."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q19","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":19,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 19\n\nA empresa Delta S.A. adquiriu uma máquina por R$ 350.000,00 em 01/01/2020. No momento da aquisição, a administração de Delta S.A. estimou a vida útil desse ativo em 10 anos e um valor residual de R$ 50.000,00. A máquina estava disponível para uso em 01/01/2020 e a empresa adotou o método de depreciação linear. Em 31/12/2023, a empresa procedeu a uma revisão das suas estimativas, conforme previsto no NBC TG 27 (R4) - ATIVO IMOBILIZADO, e constatou as seguintes informações: • Vida útil remanescente: 9 anos; • Valor Residual: R$ 50.000,00. Com base exclusivamente nas informações apresentadas, o valor da depreciação anual dessa máquina a partir de 01/01/2024 será de","options":["R$ 35.000,00.","R$ 30.000,00.","R$ 20.000,00.","R$ 15.000,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q20","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":20,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 20\n\nA NBC TG ESTRUTURA CONCEITUAL estabelece os conceitos dos elementos das demonstrações contábeis. Com base nessa norma, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Ativo é um recurso econômico presente de propriedade da entidade como resulta do de eventos passados. ( ) Passivo é uma obrigação futura da entidade de transferir um recurso econômico como resultado de eventos passados. ( ) Receitas são aumentos nos ativos, ou reduções nos passivos, que resultam em aumento no patrimônio líquido, exceto aqueles referentes a contribuições de detentores de direitos sobre o patrimônio. ( ) Despesas são reduções nos ativos, ou aumentos nos passivos, que resultam em reduções no patrimônio líquido, exceto aqueles referentes a distribuições aos detentores de direitos sobre o patrimônio. As afirmativas são, respectivamente,","options":["F – F – V – V.","F – V – F – V.","V – F – V – F.","V – V – F – F."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q21","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":21,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 21\n\nA empresa Alfa S.A. adquiriu, por R$ 1.300.000,00, no dia 01/01/2025, 80% do capital da empresa Beta S.A., adquirindo nessa data o seu controle. Na data da aquisição: 1. o valor contábil do patrimônio líquido da empresa Beta S.A. era de R$ 1.000.000,00; 2. o valor líquido dos ativos identificáveis e dos passivos da empresa Beta S.A . correspondentes a 100% de seu capital social, mensurados a valor justo, era de R$ 1.500.000,00. Com base exclusivamente nos dados apresentados e na NBC TG 15 (R4) – COMBINAÇÃO DE NEGÓCIOS, avalie as afirmativas abaixo, com relação à contabilização ocorrida na empresa Alfa S.A.: I. Foi registrado um goodwill no valor de R$ 100.000,00. II. Foi registrada uma compra vantajosa no valor de R$ 200.000,00. III. Foi registrado um ágio ou mais-valia dos ativos no valor de R$ 400.000,00. IV. Foi registrado um ágio ou mais-valia dos ativos no valor de R$ 500.000,00. Estão corretas as afirmativas","options":["I e III, apenas.","I e IV, apenas.","II e III, apenas.","II e IV, apenas."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q22","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":22,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 22\n\nInfluência significativa é o poder de participar das decisões sobre políticas financeiras e operacionais de uma investida, mas sem que haja o controle individual ou o conjunto dessas políticas. A NBC TG 18 (R4) - INVESTIMENTO EM COLIGADA determina que a existência de influência significativa por investidor geralmente é evidenciada por uma ou mais das seguintes formas, à exceção de uma. Assinale-a.","options":["Indicação de funcionários para a investida.","Operações materiais entre o investidor e a investida.","Intercâmbio de diretores ou gerentes.","Fornecimento de informação técnica essencial."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q23","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":23,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 23\n\nA empresa ABCDE possui os seguintes registros referentes às movimentações em determinado período: • Compras: ................................................................................................................................................................. R$ 5.000,00. • Estoque inicial: ........................................................................................................................................................ R$ 3.000,00. • Estoque final: .......................................................................................................................................................... R$ 2.000,00. • Vendas: ................................................................................................................................................................. R$ 30.000,00. • Despesas gerais: ..................................................................................................................................................... R$ 1.000,00. • Devolução de compras: ............................................................................................................................................. R$ 500,00. Com base nesses registros, é possível afirmar que a empresa obteve o Custo das Mercadorias Vendidas (CMV) de","options":["R$ 6.000,00.","R$ 7.500,00.","R$ 8.000,00.","R$ 5.500,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q24","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":24,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 24\n\nA empresa S.A. possuía, em 31/12/2024, obrigações presentes como resultados de eventos passados cuja saída de recursos envolvendo benefícios futuros na liquidação esteve sujeita à análise, com a classificação disposta na tabela a seguir: Tipo de Obrigação Valor da mensuração por estimativa confiável Probabilidade de ocorrência de saída de recurso Garantia de venda R$ 5.000,00 Provável Terreno contaminado e obrigação não formalizada R$ 15.000,00 Provável Processo Trabalhista I R$ 10.000,00 Remota Processo Trabalhista II R$ 20.000,00 Possível Processo Fiscal Há impossibilidade de estimar confiavelmente no momento. Possível Com base nos dados, seguindo a NBC TG 25 (R2) - PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, o montante a ser reconhecido como provisões no Balanço Patrimonial da empresa deve ser de","options":["R$ 20.000,00.","R$ 40.000,00.","R$ 30.000,00.","R$ 50.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q25","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":25,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 25\n\nA empresa Serviços S.A. encerrou seu exercício em 31/12/2024, deixando de efetuar o lançamento referente à receita de serviços prestados a um cliente em dezembro e ainda não recebidos, deixando de obedecer, assim, ao regime de competência. Como consequência do erro cometido pela ausência desse registro,","options":["o saldo da conta clientes ficou superavaliado.","o saldo do disponível ficou subavaliado.","a receita do exercício ficou superavaliada.","o lucro do exercício ficou subavaliado."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q26","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":26,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 26\n\nA Cia. Gold vende pulseiras. Em 31/12/2024, não havia estoque inicial de pulseiras. No primeiro trimestre de 2025 aconteceram os seguintes fatos: • 05/01: compra de 20 pulseiras por R$ 10.000,00; • 25/01: venda de 10 pulseiras por R$ 1.200,00 cada; • 05/02: compra de 12 pulseiras por R$ 7.200,00; • 20/02: venda de 11 pulseiras por R$ 1.200,00 cada; • 10/03: compra de 8 pulseiras por R$ 5.200,00; • 27/03: venda de 5 pulseiras por R$ 1.400,00 cada. Assinale a opção que indica o valor aproximado do estoque final de pulseiras da Cia. Gold em 31/03/2025, considerando que a empresa utiliza o método do Custo Médio Ponderado Móvel em base diária.","options":["R$ 7.840,00.","R$ 8.326,00.","R$ 9.100,00.","R$ 10.905,00."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q27","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":27,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 27\n\nUma loja de cosméticos começou a funcionar em 01/07/2024. No segundo semestre de 2024, aconteceram os seguintes fatos: • Integralização de capital social em dinheiro: R$ 300.000,00. • Compra à vista de móveis e utensílios para a loja: R$ 40.000,00. • Compra à vista de estoque para revenda: R$ 80.000,00. • Pagamento do aluguel do semestre: R$ 30.000,00. • Pagamento antecipado do aluguel do primeiro trimestre de 2025: R$ 18.000,00. • Venda de todo o estoque por R$ 400.000,00, sendo que metade do valor já foi recebido e o restante deverá ser recebido no primeiro semestre de 2025. A loja estima inadimplência de 5%. • Reconhecimento e pagamento de despesas diversas: R$ 12.000,00. • Reconhecimento da despesa de depreciação: R$ 4.000,00. O fluxo de caixa gerado pela atividade operacional em 2024, de acordo com as diretrizes da NBC TG 03 (R3) – DEMONSTRAÇÃO DOS FLUXOS DE CAIXA foi de","options":["R$ 20.000,00.","R$ 50.000,00.","R$ 60.000,00.","R$ 360.000,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q28","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":28,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 28\n\nEm 01/12/2024, uma sociedade empresária apresentava, em seu Balanço Patrimonial, como ativo imobilizado, um terreno, cujo valor contábil era de R$ 80.000,00. Em 31/12/2024, a sociedade empresária realizou um teste de recuperabilidade em seus ativo s imobilizados. Foi constatado que o valor em uso do terreno era de R$ 75.000,00. Para que não haja reconhecimento de perda de recuperabilidade do terreno, o valor justo líquido de despesa de venda deve ser","options":["menor do que R$ 75.000,00.","maior do que R$ 79.999,99.","entre R$ 72.000,00 e R$ 74.999,99.","entre R$ 75.000,00 e R$ 79.999,99."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q29","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":29,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 29\n\nEm junho de 2025, uma companhia aérea reconheceu as seguintes receitas: • com a marcação de assentos: R$ 150.000,00; • com equivalência patrimonial: R$ 200.000,00; • com a venda de passagens: R$ 900.000,00. Nesse mês, a companhia aérea reconheceu como Receita, na primeira linha da Demonstração do Resultado do Exercício, o seguinte montante:","options":["R$ 900.000,00.","R$ 1.050.000,00.","R$ 1.100.000,00.","R$ 1.250.000,00."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q30","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":30,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 30\n\nEm 01/01/2025, uma livraria tinha em estoque 20 livros “Estatística Simples”. Cada livro tinha sido adquirido por R$ 80,00 e era vendido por R$ 140,00. No primeiro trimestre desse ano, a movimentação do livro foi a seguinte: • 28/01: venda de 10 livros por R$ 140,00. • 05/02: compra de 15 livros por R$ 90,00. • 25/02: venda de 18 livros por R$ 150,00. • 05/03: compra de 20 livros por R$ 95,00. • 28/03: venda de 25 livros por R$ 150,00. O custo das mercadorias vendidas no primeiro trimestre de 2025, considerando que a livraria utiliza o método PEPS para avaliação de estoque, foi de","options":["R$ 3.860,00.","R$ 4.220,00.","R$ 4.660,00.","R$ 5.035,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q31","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":31,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 31\n\nA compreensão dos conceitos e métodos relacionados à Demonstração do Resultado do Exercício (DRE) e à Demonstração do Resultado Abrangente (DRA) é fundamental para a adequada análise das variações do patrimônio líquido e para a tomada de decisões baseadas nos resultados operacionais. A respeito do tema, analise as seguintes afirmativas: I. A recompra de ações de emissão da própria entidade para manutenção em tesouraria afeta o resultado abrangente por representar uma redução no patrimônio líquido. II. O resultado abrangente compreende todos os componentes da demonstração do resultado e dos outros resultados abrangentes. III. Pelo método da natureza da despesa, as despesas são classificadas conforme sua função, como administrativas, comerciais e de produção, facilitando a análise do custo dos produtos vendidos. IV. A informação sobre a natureza das despesas é útil para prever os fluxos de caixa futuros e requer divulgação adicional quando a classificação adotada na DRE for baseada no método da função das despesas. V. A entidade deve apresentar rubricas ou itens de receitas ou despesas como itens extraordinários, quer na demonstração do resultado abrangente, quer na demonstração do resultado do período, quer nas notas explicativas. De acordo com a NBC TG 26 (R5) - APRESENTAÇÃO DAS DEMONSTRAÇÕES CONTÁBEIS, estão corretas as afirmativas","options":["II e IV, apenas.","I, III e V, apenas.","II, III e IV, apenas.","I, II, IV e V, apenas."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q32","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":32,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 32\n\nA empresa S.A. é especializada na construção de galpões industriais sob encomenda de acordo com especificações exclusivas de cada cliente. Os contratos firmados pela empresa preveem que a construção ocorra no terreno do cliente, com pagamentos mensais vinculados ao andamento da obra, que pode durar de 6 a 10 meses. Considerando as informações apresentadas e os preceitos da NBC TG 47 – RECEITA DE CONTRATO COM CLIENTE, o reconhecimento da receita deve ocorrer","options":["somente após a emissão do certificado de aceitação técnica da obra pelo cliente.","no momento da conclusão da obra, quando todos os riscos e benefícios são transferidos.","no início do contrato, pois o pagamento mensal caracteriza o reconhecimento da receita.","ao longo do tempo, pois o desempenho da entidade cria ou melhora ativo que o cliente controla à medida que é construído."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q33","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":33,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 33\n\nUma empresa S.A. celebrou um contrato no valor de R$ 30.000,00 para utilizar um equipamento por um período de 10 meses, cujo ativo subjacente do contrato foi considerado de baixo valor pela empresa. A administração da empresa S.A. decidiu aplicar a isenção de reconhecimento autorizada pelo item 5 da NBC TG 06 (R3). Considerando-se as informações apresentadas e os preceitos da NBC TG 06 (R3) – ARRENDAMENTOS, o tratamento contábil para esse contrato é","options":["registrar o valor total do contrato antecipadamente como despesa no início do contrato.","capitalizar o valor do contrato como ativo imobilizado, amortizando ao longo do contrato.","reconhecer os pagamentos do arrendamento como despesa no resultado, de forma linear ou sistemática, ao longo do prazo do contrato.","reconhecer um ativo de direito de uso e um passivo de arrendamento, ambos, ao valor presente estipulado no contrato."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q34","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":34,"subject":"Contabilidade Geral","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 34\n\nUma empresa que atua na produção de medicamentos há 10 anos decidiu trocar dois de seus equipamentos (classificados como ativo imobilizado) mais relevantes por outros com tecnologia mais atualizada com o objetivo de redução nos seus custos de produção. As informações sobre os equipamentos retirados de operação são relatadas a seguir: Equipamento 1 Valor Contábil Líquido = R$ 500.000,00 Valor Justo Líquido = R$ 750.000,00 Equipamento 2 Valor Contábil Líquido = R$ 1.500.000,00 Valor Justo Líquido = R$ 1.250.000,00 Sabendo que os novos equipamentos adquiridos já estão em uso, um plano de venda desses ativos (Equipamentos 1 e 2) foi submetido e aprovado pelo Conselho de Administração, que considerou a venda altamente provável de ser concluída nos próximos 12 meses. Logo, segundo a NBC TG 31 (R3) – ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA, a mensuração subsequente dos equipamentos a ser adotada pela empresa a partir da decisão do Conselho de Administração é:","options":["Equipamento 1 por R$ 500.000,00 e Equipamento 2 por R$ 1.250.000,00.","Equipamento 1 por R$ 500.000,00 e Equipamento 2 por R$ 1.500.000,00.","Equipamento 1 por R$ 750.000,00 e Equipamento 2 por R$ 1.500.000,00.","Equipamento 1 por R$ 750.000,00 e Equipamento 2 por R$ 1.250.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q35","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":35,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 35\n\nA Contabilidade de Custos possui uma linguagem própria que permite ao profissional da contabilidade constituir o processo de análise, apuração e divulgação das in formações relacionadas a custos, à medida que se mostrarem pertinentes de acordo com a necessidade informacional dos inúmeros stakeholders. Tomando por base esse processo de terminologias na contabilidade de custos, assinale a afirmativa correta.","options":["Os gastos representam a compra de um produto ou serviço que tem por capacidade gerar o dispêndio de recursos financeiros por parte da empresa, a exemplo da aquisição de um imobilizado.","Os custos representam um sacrifício monetário referente ao pagamento dos gastos, a exemplo do consumo de matéria-prima.","As despesas podem ser entendidas como os recursos utilizados na constituição de bens ou serviços em uma indústria, como exemplo tem-se as despesas com vendas e comissões.","As perdas são gastos anormais e involuntários do processo produtivo e já estão incluídas no custo do produto."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q36","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":36,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 36\n\nUma empresa realizou a contagem de seus estoques, acabando por superavaliar o estoque inicial, mantendo o controle de compras e estoque final nos valores corretos. Em consequência da superavaliação do estoque inicial é correto afirmar que","options":["a receita de vendas do período corrente foi subavaliada.","o lucro acumulado do período corrente foi superavaliado.","o custo dos produtos vendidos do período corrente foi superavaliado.","o estoque final foi subavaliado."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q37","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":37,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 37\n\nA Fazenda Laticínios Campo Verde Ltda. produz e comercializa queijos artesanais tipo minas frescal. No mês de julho de 2025, quando a empresa não possuía estoque inicial, foram produzidas 12.000 unidades de queijo. Nesse mesmo mês, vendeu 9.000 unidades a um preço unitário de R$ 25,00. Os custos variáveis totais somaram R$ 135.000,00 e os custos fixos totalizaram R$ 42.000,00. As despesas fixas totalizaram R$ 25.000,00, e as despesas variáveis com comissão aos vendedores corresponderam a 5% do valor de cada unidade vendida. Considerando os dados fornecidos e desconsiderando efeitos tributários, os lucros líquidos com as vendas em julho de 2025, utilizando, respectivamente, os métodos de custeio por absorção e custeio variável, foram de","options":["R$ 45.470,00 e R$ 11.750,00.","R$ 56.000,00 e R$ 56.000,00.","R$ 45.470,00 e R$ 112.500,00.","R$ 56.000,00 e R$ 45.500,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q38","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":38,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 38\n\nA Indústria Paranaguá Ltda. utiliza o sistema de custeio baseado em atividades (ABC). No mês de junho de 2025, foram apuradas as seguintes informações para os produtos X, Y e Z: Produto Material Direto (R$) Mão de Obra Direta (R$) Pedidos de Mudança Quilowatts-hora (kWh) X 35.000,00 18.000,00 28 12.000 Y 40.000,00 12.000,00 20 14.000 Z 25.000,00 10.000,00 32 14.000 Total 100.000,00 40.000,00 80 40.000 Os custos indiretos de manufatura totalizaram R$ 200.000,00, distribuídos entre as seguintes atividades: • Gerenciamento de mudanças de projeto (baseado em pedidos): R$ 140.000,00; • Geração e uso de energia operacional (baseado em kWh): R$ 60.000,00. No período, foram produzidas 1.200 unidades do produto X, 1.500 unidades do produto Y e 2.000 unidades do produ to Z. Com base nesses dados, os custos unitários dos produtos X, Y e Z, respectivamente, são","options":["R$ 98,50; R$ 70,00; R$ 60,00.","R$ 90,00; R$ 80,00; R$ 65,00.","R$ 105,00; R$ 74,00; R$ 52,00.","R$ 100,00; R$ 72,00; R$ 56,00."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q39","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":39,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 39\n\nEm 31/12/2023, uma sociedade empresária apresentava os seguintes saldos em seus ativos e passivos: • Ativo Circulante: R$ 50.000,00; • Ativo Realizável a Longo Prazo: R$ 30.000,00; • Ativo Imobilizado: R$ 120.000,00; • Passivo Circulante: R$ 40.000,00; • Passivo não Circulante: R$ 100.000,00. A proporção de capital próprio que financia o ativo da sociedade empresária foi igual a","options":["30%.","40%.","60%.","70%."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q40","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":40,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 40\n\nUma fábrica produz e vende apenas malas de mão. O custo fixo mensal da fábrica é de R$ 10.000,00. As malas são produzidas em dois modelos: com duas rodinhas e com quatro rodinhas. As malas com duas rodinhas são vendidas por R$ 200,00 cada, enquanto as malas com quatro rodinhas são vendidas por R$ 370,00 cada. Além disso, o custo variável da mala com duas rodinhas é de R$ 80,00, e o custo variável da de quatro rodinhas é de R$ 140,00. No primeiro trimestre de 2025, a fábrica tinha em estoque 500 unidades de rodinhas e não era possível adquirir mais. No período, as demandas pela produção de malas com duas e quatro rodinhas eram, respectivamente, de 80 e de 100. Considerando que a fábrica tinha como objetivo maximizar o seu lucro, assinale a opção que indic a a produção de malas de duas e quatro rodinhas, respectivamente, no período.","options":["50 e 85.","50 e 100.","80 e 85.","80 e 100."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q41","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":41,"subject":"Contabilidade de Custos","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 41\n\nA empresa Gigulefere S.A. adota o custo padrão e verificou, em abril de 2025, alguns dados para analisar a variação ocorrida (realizado x orçado). Abaixo estão apresentados os dados apurados pelo contador: • a mão de obra direta efetivamente consumida foi 50 horas superior ao padrão estabelecido de 1.500 horas. • o custo incorrido com a mão de obra direta, por unidade de tempo, ficou R$ 7,00 abaixo do valor previsto de R$ 150,00 por hora. Com base exclusivamente nos dados apresentados pelo contador, as variações de taxa e eficiência, respectivamente, ocorridas no mês de abril de 2025, foram","options":["350 desfavorável e 225.000 favorável.","10.500 favorável e 7.500 desfavorável.","75.000 desfavorável e 225.000 favorável.","1.050 favorável e 75.000 desfavorável."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q42","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":42,"subject":"Contabilidade Aplicada ao Setor Público","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 42\n\nEm janeiro de 2024, um município adquiriu computadores para o edifício -sede da Prefeitura por R$ 50.000,00, classificando- os como ativo imobilizado. O transporte do estabelecimento do fornecedor para o edifício foi de R$ 5.000,00, pagos pelo município. Além disso, os custos de preparação dos locais para a instalação dos computadores foram de R$ 10.000,00. Após estarem devidamente instalados, o município gastou R$ 8.000,00 para treinar os funcionários que utilizarão esses computadores. O valor a ser reconhecido a título desse ativo, inicialmente, é","options":["R$ 55.000,00.","R$ 63.000,00.","R$ 65.000,00.","R$ 73.000,00."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q43","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":43,"subject":"Contabilidade Aplicada ao Setor Público","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 43\n\nUma escola do setor público serve, diariamente, café da manhã e almoço a seus alunos. Para as refeições, a escola adquire, semanalmente, frutas e verduras, e trimestralmente, alimentos não perecíveis. Todas as compras são pagas à vista. Em julho, a escola gastou R$ 4.000,00 com frutas e verduras e R$ 20.000,00 com os produtos não perecíveis, para serem estocados e utilizados até setembro. Os caixas consumidos, respectivamente, pela Atividade Operacional e pela Atividade de Investimento, na Demonstração dos Fluxos de Caixa da escola, foram","options":["zero e R$ 24.000,00.","R$ 4.000,00 e R$ 20.000,00.","R$ 20.000,00 e R$ 4.000,00.","R$ 24.000,00 e zero."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q44","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":44,"subject":"Contabilidade Aplicada ao Setor Público","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 44\n\nDe acordo com a NBC TSP - RECEITA DE TRANSAÇÃO SEM CONTRAPRESTAÇÃO, quando uma entidade do setor público adquire um ativo por meio de uma transação sem contraprestação, esse ativo deve ser mensurado inicialmente","options":["pelo valor de ativo similar adquirido nos último três anos pela entidade pública.","pelo valor simbólico de R$ 1,00.","pelo valor justo do ativo na data de aquisição.","por valor nenhum, considerando que não houve pagamento na transação."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q45","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":45,"subject":"Contabilidade Gerencial","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 45\n\nNo planejamento orçamentário, a projeção da receita líquida de vendas é fundamental para estimar os resultados financeiros do período. Para isso, devem ser consideradas as quantidades a serem vendidas, o preço unitário e eventuais descontos concedidos. Uma empresa projeta vender 4.000 unidades de seu produto no próximo trimestre. O preço de venda unitário é de R$ 120,00, e a empresa oferece um desconto comercial de 5% sobre o valor total. Considerando essas premissas, o valor estimado da receita líquida de vendas no orçamento trimestral será de","options":["R$ 456.000,00.","R$ 480.000,00.","R$ 484.000,00.","R$ 504.000,00."],"answer":0,"officialAnswer":"A","annulled":false,"explanation":"Gabarito definitivo oficial: A. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q46","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":46,"subject":"Controladoria","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 46\n\nDurante a reestruturação de uma empresa, o contador passou a atuar estrategicamente na controladoria e no compliance, contribuindo para o aprimoramento da gestão, monitorando indicadores e apoiando decisões. Ele também assegurou a conformidade com normas legais e regulatórias. Com isso, fortaleceu seu papel na governança e na transparência organizacional. Considerando essa atuação conjunta, uma atribuição que caracteriza adequadamente essa integração funcional é","options":["a mitigação de riscos.","o acompanhamento de metas.","o monitoramento da integridade dos controles internos.","o apoio à gestão com foco em desempenho e conformidade."],"answer":3,"officialAnswer":"D","annulled":false,"explanation":"Gabarito definitivo oficial: D. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q47","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":47,"subject":"Auditoria","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 47\n\nUm Auditor foi contratado por uma determinada empresa S.A. para realizar auditoria independente e, na ocasião, deparou com a seguinte situação: nos demonstrativos auxiliares, verificou-se que a empresa adota o método linear de depreciação das máquinas e registra o lançamento mensalmente na contabilidade. Conforme a NBC TA 500 (R1) - EVIDÊNCIA DE AUDITORIA, o procedimento que deverá ser adotado para a confirmação da exatidão dos valores lançados é","options":["a confirmação externa.","a inspeção.","o recálculo.","a indagação."],"answer":2,"officialAnswer":"C","annulled":false,"explanation":"Gabarito definitivo oficial: C. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q48","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":48,"subject":"Auditoria","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 48\n\nDe acordo com a NBC TA 300 (R1) – PLANEJAMENTO DA AUDITORIA DE DEMONSTRAÇÕES CONTÁBEIS, o envolvimento do sócio do trabalho e de outros membros-chave da equipe de trabalho no planejamento da auditoria","options":["garante o controle e o cumprimento das etapas necessárias, fornecendo agilidade ao processo de planejamento.","incorpora a sua experiência e seus pontos de vista, otimizando a eficácia e a eficiência do processo de planejamento.","aumenta a admiração e o respeito transferidos pela equipe, proporcionando sinergia para o processo de planejamento.","melhora a proximidade e o relacionamento com a equipe, contribuindo para a qualidade do processo de planejamento."],"answer":1,"officialAnswer":"B","annulled":false,"explanation":"Gabarito definitivo oficial: B. Consulte o enunciado e a alternativa correta ao revisar este item.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q49","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":49,"subject":"Perícia Contábil","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 49\n\nConsiderando as disposições da NBC TP 01 (R1) - PERÍCIA CONTÁBIL, avalie as assertivas a seguir. I. A perícia contábil é o conjunto de procedimentos técnico -científicos destinados a levar à instância decisória elementos de prova necessários a subsidiar a justa solução do litígio ou constatação de fato, mediante laudo pericial contábil e/ou parecer pericial contábil, em conformidade com as normas jurídicas e profissionais e com a legislação específica no que for pertinente. II. O laudo pericial contábil e o parecer pericial contábil não têm por limite o objeto da perícia deferida ou contratada. III. A perícia contábil é de competência do contador em situação regular em Conselho Regional de Contabilidade ou de profissional equivalente, desde que seja detentor de notório conhecimento sobre a matéria. IV. O planejamento da perícia é a etapa do trabalho pericial na qual o perito estabelece as diretrizes e a metodologia a serem aplicadas. Estão corretas apenas as assertivas","options":["I e II.","I e III.","II e III.","I e IV."],"answer":null,"officialAnswer":"Anulada","annulled":true,"explanation":"Questão anulada no gabarito definitivo da FGV; não pontua.","unit":"Revisão por disciplina"},{"id":"cfc-2025.2-tipo1-q50","examId":"2025.2-tipo1","examLabel":"2025.2 — Tipo 1","number":50,"subject":"Perícia Contábil","source":"Exame de Suficiência 2025.2 — Tipo 1; gabarito definitivo FGV","text":"Questão 50\n\nO Parecer Pericial Contábil é um documento elaborado pelo perito -contador assistente, destinado a analisar, comentar ou contestar o Laudo Pericial Contábil elaborado pelo perito-contador nomeado pelo juízo. O parecer deve ser redigido de forma clara, objetiva e técnica, seguindo rigorosamente as normas contábeis. Segundo a NBC TP 01 - PERÍCIA CONTÁBIL, uma condição para a emissão do Parecer Pericial Contábil é que o Parecer Pericial Contábil deve","options":["ser emitido, independentemente de concordância ou discordância com o Laudo Pericial Contábil.","ser emitido apenas quando houver concordância total com o Laudo Pericial Contábil.","ser emitido somente se houver divergência parcial ou total em relação ao Laudo Pericial Contábil.","ser emitido contendo uma análise sobre a conduta do perito-contador responsável pelo Laudo Pericial Contábil. Realização"],"answer":null,"officialAnswer":"Anulada","annulled":true,"explanation":"Questão anulada no gabarito definitivo da FGV; não pontua.","unit":"Revisão por disciplina"}];

